typedef struct {
    int id;
    char name[16];
} Config;

// Pointer to Const: Ensures data pointed to is read-only
void safe_read(const Config* cfg) {
    // cfg->id = 10; // Compile Error: Cannot modify const data
    int value = cfg->id; // OK
    (void)value;
}

// Function usage
Config global_config = {1, "System A"};
safe_read(&global_config);

// Key distinction:
const Config* ptr1; // Data is const
Config* const ptr2 = 0; // Pointer is const, data mutable
(void)ptr1;
(void)ptr2;
